package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class MonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoanPort loadLoanPort;

    public MonthlyStatsService(LoadLoanPort loadLoanPort) {
        this.loadLoanPort = loadLoanPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(int year, int month) {
        YearMonth yearMonth = toYearMonth(year, month);
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.atEndOfMonth();

        long loanCount = loadLoanPort.countLoansLoanedBetween(from, to);
        List<Loan> returned = loadLoanPort.loadLoansReturnedBetween(from, to);
        // 연체료 계산 규칙은 도메인 Loan 에 있으므로 여기서는 연체료가 0보다 큰 반납만 골라 합산한다.
        List<Long> lateFees = returned.stream()
                .map(Loan::lateFee)
                .filter(lateFee -> lateFee > 0)
                .toList();
        long lateFeeTotal = lateFees.stream().mapToLong(Long::longValue).sum();

        return new MonthlyStats(year, month, loanCount, returned.size(), lateFees.size(), lateFeeTotal);
    }

    // YearMonth.of 는 범위를 벗어나면 DateTimeException 을 던지므로, 웹 계층에서 400 으로 응답하도록 바꾼다.
    private static YearMonth toYearMonth(int year, int month) {
        try {
            return YearMonth.of(year, month);
        } catch (DateTimeException e) {
            throw new IllegalArgumentException(e.getMessage(), e);
        }
    }
}

