package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// 다른 테스트의 대출(2026년)과 겹치지 않도록 1990년 기간의 데이터만 쓴다.
@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void counts_loans_by_loan_date_and_returns_and_late_fees_by_return_date() throws Exception {
        String member = registerMember("성하윤");
        // 2월에 빌려 3월에 늦게 반납: 대출일은 2월, 반납일은 3월이다. 기한 1990-02-15, 반납 1990-03-03 → 16일 연체 1600원
        loanBook(registerBook(), member, "1990-02-01");
        loanBook(registerBook(), member, "1990-02-10");
        // 3월 대출, 3월 정시 반납
        loanBook(registerBook(), member, "1990-03-01");
        String returnedOnTime = loanBook(registerBook(), member, "1990-03-01");
        // 3월 대출, 미반납
        loanBook(registerBook(), member, "1990-03-05");

        // 2월 대출 중 3월 말에 반납: 기한 1990-02-24, 반납 1990-03-31 → 35일 연체 3500원
        String lateAcrossMonth = findLoanId(member, "1990-02-10");
        returnLoan(lateAcrossMonth, "{\"returnedAt\":\"1990-03-31\"}").andExpect(status().isOk());
        returnLoan(findLoanId(member, "1990-02-01"), "{\"returnedAt\":\"1990-03-03\"}").andExpect(status().isOk());
        returnLoan(returnedOnTime, "{\"returnedAt\":\"1990-03-10\"}").andExpect(status().isOk());

        mockMvc.perform(get("/stats/monthly").param("year", "1990").param("month", "3"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(1990))
                .andExpect(jsonPath("$.month").value(3))
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(3))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(5100));
    }

    @Test
    void a_month_without_activity_is_all_zero() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "1990").param("month", "7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(1990))
                .andExpect(jsonPath("$.month").value(7))
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void a_month_outside_1_to_12_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "1990").param("month", "13"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/stats/monthly").param("year", "1990").param("month", "0"))
                .andExpect(status().isBadRequest());
    }

    ResultActions returnLoan(String loanId, String body) throws Exception {
        return mockMvc.perform(post("/loans/{loanId}/return", loanId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(body));
    }

    String findLoanId(String memberId, String loanedAt) throws Exception {
        String history = mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andReturn().getResponse().getContentAsString();
        for (JsonNode loan : objectMapper.readTree(history)) {
            if (loan.get("loanedAt").asText().equals(loanedAt)) {
                return loan.get("loanId").asText();
            }
        }
        throw new AssertionError("loan not found: " + loanedAt);
    }

    String loanBook(String bookId, String memberId, String loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Code\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }
}

